import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.cyF4XceO.js";const g=JSON.parse('{"title":"バージョンと互換性","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/versions.md","filePath":"ja/docs/versions.md"}'),d={name:"ja/docs/versions.md"};function i(s,t,n,c,h,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="バージョンと互換性" tabindex="-1">バージョンと互換性 <a class="header-anchor" href="#バージョンと互換性" aria-label="Permalink to &quot;バージョンと互換性&quot;">​</a></h1><p>Provider の版は client schema と exact Form の対応表を選びます。 Form の公開や Host の対応を保証するものではありません。Form definition の版、 package digest、Host API の版はそれぞれ独立した owner と履歴を持ちます。</p><h2 id="インストールする版と評価するソース" tabindex="-1">インストールする版と評価するソース <a class="header-anchor" href="#インストールする版と評価するソース" aria-label="Permalink to &quot;インストールする版と評価するソース&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>この repository での状態</th><th>Host API</th><th>対応表</th><th>参照先</th></tr></thead><tbody><tr><td><strong>4.1.0</strong></td><td>Registry 公開済み</td><td><code>forms.takoform.com/v1</code></td><td>Edge Form 17 種</td><td><a href="/ja/docs/getting-started.html">入門ガイド</a></td></tr><tr><td><strong>5.0.0</strong></td><td>ソースの target</td><td><code>forms.takoform.com/v2</code></td><td>exact Edge Form URL 13 種</td><td><a href="/docs/provider-host-api-v2-source.html">Provider 5（英語）</a></td></tr></tbody></table><p>4.1.0 の署名済み tag、GitHub Release、Registry readback は <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">Provider release identity ledger</a> にあります。<a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/candidates/provider-v5.0.0.json" target="_blank" rel="noreferrer">5.0.0 descriptor</a> はソースの target を指定するもので、Registry からのインストールを証明しません。 pin を変える前に<a href="https://registry.terraform.io/providers/tako0614/takoform/latest" target="_blank" rel="noreferrer">Registry の公開一覧</a>と exact version の readback を確認してください。</p><p><strong>Provider 4 の state は Provider 5 へ自動変換されません。</strong> 既存 v4 workspace の 移行は別に計画し、検証する必要があります。ソースから通常 build した plugin は v2 を使い、 v2 での失敗時に v1 へ切り替えません。</p><h2 id="provider-4-の-identity" tabindex="-1">Provider 4 の identity <a class="header-anchor" href="#provider-4-の-identity" aria-label="Permalink to &quot;Provider 4 の identity&quot;">​</a></h2><p>4.1.0 の Edge Form 17 種の公開正本は <a href="https://github.com/tako0614/takoform-forms/commit/3231633605b737ce5279d7fc020b4780568e7091" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3231633605b737ce5279d7fc020b4780568e7091</code></a> です。resource state は group、kind、<code>definitionVersion</code>、<code>schemaDigest</code> の 4 フィールドからなる exact FormRef を記録し、package digest は別に package bytes を識別します。 <a href="/forms/candidates/edge.forms.takoform.com/candidate-set.json">embedded candidate snapshot</a>の <code>publicationStatus: unpublished</code> は外部での公開 evidence ではありません。 Core v1.0.1 への参照はこの v1 reference の互換性 checkpoint です。</p><p>Provider 5 は <code>form_url</code> に exact publisher Form URL を記録し、独自の schema と private intent-store 契約を使います。13 種の対応表と exact definition version は Provider 5 reference にあります。</p><h2 id="公開済み版の互換性履歴" tabindex="-1">公開済み版の互換性履歴 <a class="header-anchor" href="#公開済み版の互換性履歴" aria-label="Permalink to &quot;公開済み版の互換性履歴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Host API lane</th><th>互換性</th></tr></thead><tbody><tr><td><strong>4.1.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>token file と pending-operation custody に対応。Form identity は 4.0.0 と同一。</td></tr><tr><td><strong>4.0.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>publisher set の Edge Form 17 種。静的 token に対応。</td></tr><tr><td><strong>3.0.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>8 family / 31 Form の不変の aggregate release。</td></tr><tr><td><strong>2.1.1</strong></td><td><code>forms.takoform.com/v1beta1</code></td><td><a href="/release/provider-form-identities.json">identity ledger</a>にある 15 種の不変の Edge Form。</td></tr><tr><td><strong>2.0.0</strong></td><td>withdrawn <code>v1alpha2</code> epoch</td><td>exact-pin recovery と移行の履歴。</td></tr><tr><td><strong>1.0.3</strong></td><td>withdrawn <code>v1alpha1</code> epoch</td><td>exact-pin recovery と移行の履歴。</td></tr></tbody></table><p>withdrawn epoch の state は<a href="/release/migrations/v2-to-v3.html">v2-to-v3 migration（英語）</a>、 Provider 3 からの更新は<a href="/release/migrations/v3-to-v4.html">v3-to-v4 publisher-set boundary（英語）</a> を確認してください。自動 migration はありません。</p><p>不変の v4.1.0 tag には公開前の文言が残り、4.1.0 を candidate と呼んで v4.0.0 を案内しています。 現行 ledger はその後の Registry readback を記録します。tag と Registry に表示される tag 由来の 文書を上書きせず、修正された Registry 文書は新しい版で提供します。</p><p>公開 receipt と実行可能な検証の範囲は<a href="/release/">Release evidence（英語）</a>と <a href="/conformance/">Conformance（英語）</a>を参照してください。</p>',14)])])}const p=e(d,[["render",i]]);export{g as __pageData,p as default};
